mapper.select:
SELECT calc.YIELD
FROM FIN_CASH_INFO info,
     FIN_CASH_CALC_RULE calc
WHERE info.FINPROD_ID = #{finProdId, jdbcType=VARCHAR}
AND info.CASH_TYPE_2 = #{cashType, jdbcType=VARCHAR}
AND info.CASH_ID = calc.CASH_ID
AND calc.EFF_DATE = (
    SELECT MAX(calc.EFF_DATE)
    FROM FIN_CASH_CALC_RULE calc2
    WHERE DATE_FORMAT(calc2.EFF_DATE, '%Y%m%d') <= #{cdate, jdbcType=VARCHAR}
    AND info.CASH_ID = calc2.CASH_ID
)
